#include <string>
#include <vector>
#include <algorithm>
#include <cmath>

class Solution {
private:
    std::vector<int> findAll(const std::string& s, const std::string& pat) {
        std::vector<int> res;
        size_t pos = s.find(pat);
        while (pos != std::string::npos) {
            res.push_back(pos);
            pos = s.find(pat, pos + 1);
        }
        return res;
    }
public:
    std::vector<int> beautifulIndices(std::string s, std::string a, std::string b, int k) {
        auto aIdx = findAll(s, a);
        auto bIdx = findAll(s, b);
        if (aIdx.empty() || bIdx.empty()) return {};
        std::vector<int> ans;
        for (int i : aIdx) {
            auto it = std::lower_bound(bIdx.begin(), bIdx.end(), i);
            bool found = false;
            if (it != bIdx.end() && std::abs(*it - i) <= k) found = true;
            else if (it != bIdx.begin() && std::abs(*std::prev(it) - i) <= k) found = true;
            if (found) ans.push_back(i);
        }
        return ans;
    }
};

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class Solution {
    private List<Integer> findAll(String s, String pat) {
        List<Integer> res = new ArrayList<>();
        int pos = s.indexOf(pat);
        while (pos != -1) {
            res.add(pos);
            pos = s.indexOf(pat, pos + 1);
        }
        return res;
    }

    public List<Integer> beautifulIndices(String s, String a, String b, int k) {
        List<Integer> aIdx = findAll(s, a);
        List<Integer> bIdx = findAll(s, b);
        if (aIdx.isEmpty() || bIdx.isEmpty()) return new ArrayList<>();
        List<Integer> ans = new ArrayList<>();
        for (int i : aIdx) {
            int idx = Collections.binarySearch(bIdx, i);
            if (idx >= 0) {
                ans.add(i);
            } else {
                int ins = -idx - 1;
                boolean found = false;
                if (ins < bIdx.size() && Math.abs(bIdx.get(ins) - i) <= k) found = true;
                else if (ins > 0 && Math.abs(bIdx.get(ins - 1) - i) <= k) found = true;
                if (found) ans.add(i);
            }
        }
        return ans;
    }
}

var beautifulIndices = function(s, a, b, k) {
    function findAll(pat) {
        const res = [];
        let pos = s.indexOf(pat);
        while (pos !== -1) {
            res.push(pos);
            pos = s.indexOf(pat, pos + 1);
        }
        return res;
    }
    const aIdx = findAll(a);
    const bIdx = findAll(b);
    if (aIdx.length === 0 || bIdx.length === 0) return [];
    const ans = [];
    for (const i of aIdx) {
        let l = 0, r = bIdx.length - 1;
        let found = false;
        while (l <= r) {
            const mid = (l + r) >> 1;
            if (Math.abs(bIdx[mid] - i) <= k) {
                found = true;
                break;
            }
            if (bIdx[mid] < i) l = mid + 1;
            else r = mid - 1;
        }
        if (found) ans.push(i);
    }
    return ans;
};
